(()=>{'use strict';const $=id=>document.getElementById(id),esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let courses=[],account=null,state={quizPassed:[],tasks:{},ratings:{},codeDrafts:{},memory:{enabled:false,notes:'',turns:[],epoch:0}},summary={points:0,credits:0,coursesCompleted:[],tasksCompleted:0,quizzesPassed:0,level:'Launch'},dirty=new Set(),error='',guest=false,worker=null;const route=location.pathname.split('/')[1],params=new URLSearchParams(location.search);const url=(c,l,tab)=>'/academy?course='+encodeURIComponent(c.id)+(l?'&lesson='+encodeURIComponent(l.id):'')+(tab?'&tab='+tab:'');const allTasks=()=>courses.flatMap(c=>[...c.lessons.map(l=>({...l.task,course:c,lesson:l,capstone:false})),{...c.capstone,id:c.id+'-capstone',course:c,capstone:true}]);const complete=l=>state.quizPassed.includes(l.id)&&!!state.tasks[l.task.id];const button=(link,text,outline=false)=>`<a class="button ${outline?'outline':''}" href="${link}">${text}</a>`;const head=(e,t,s)=>`<p class="eyebrow">${e}</p><h1 class="page-title">${t}</h1><p class="page-subtitle">${s}</p>`;function statusBanner(){return error?`<div class="notice error">${esc(error)} Refresh to retry. Your account records are not shown until connected.</div>`:guest?`<div class="notice">Explore the complete courses as a guest. <a href="/signin-with-chatgpt?return_to=${encodeURIComponent(location.pathname+location.search)}">Sign in</a> to save work, earn learning points and use account memory.</div>`:'';}async function request(body){const ctrl=new AbortController(),timer=setTimeout(()=>ctrl.abort(),15000);try{const r=await fetch('/api/academy',{method:body?'POST':'GET',credentials:'same-origin',cache:'no-store',signal:ctrl.signal,headers:body?{'Content-Type':'application/json'}:undefined,body:body?JSON.stringify({account,...body}):undefined});const value=await r.json();if(!r.ok)throw Object.assign(Error(value.error||'Could not save. Keep your work and retry.'),{status:r.status});if(account&&account!==value.account)throw Error('Your account changed. Reload before continuing.');account=value.account;state=value.state;summary=value.summary;return value;}finally{clearTimeout(timer);}}
function courseCard(c){const n=c.lessons.filter(complete).length,done=summary.coursesCompleted.includes(c.id);return `<article class="academy-course"><span class="tag">${esc(c.level)}</span><h2>${esc(c.title)}</h2><p>${esc(c.summary)}</p><div class="course-meta"><span>${c.lessons.length} DETAILED LESSONS</span><span>~${c.estimatedHours} STUDY HOURS</span><span>${c.credits} LEARNING CREDITS</span></div><div class="academy-progress" aria-label="${n} of ${c.lessons.length} lessons completed"><span style="width:${100*n/c.lessons.length}%"></span></div><p>${done?'Course completed ✓':n+' / '+c.lessons.length+' lesson checkpoints and tasks complete'}</p><div class="button-row">${button(url(c),'Explore course ↗')}${done?'<span class="tag">CREDITS EARNED</span>':''}</div></article>`;}
function academyHome(){return head('AI ACADEMY / FROM FOUNDATIONS TO SYSTEMS','BUILD REAL UNDERSTANDING.','Start at the right level. Learn the details, trace the examples, test your ideas and build something independently.')+statusBanner()+`<div class="notice">Original written courses, practical labs and self-assessed projects. Credits and points are CodeTrail learning achievements, not academic accreditation or proof of professional proficiency. Study-hour estimates include independent practice and vary by learner.</div><div class="academy-banner"><input class="academy-search" id="academy-search" type="search" placeholder="Search AI courses and lesson topics…" aria-label="Search AI courses"><div class="level-filter" role="group" aria-label="Course level"><button class="active" data-level="all">All levels</button><button data-level="beginner">Beginner</button><button data-level="intermediate">Intermediate</button><button data-level="advanced">Advanced</button></div></div><div id="academy-courses" class="academy-grid">${courses.map(courseCard).join('')}</div><div class="section-head"><h2>Keep your programming foundations strong</h2></div><section class="panel"><p>Use the existing Python and data structures course alongside these AI tracks. Java basics remain available too.</p>${button('/catalog','Open programming catalog ↗',true)}</section>`;}
const list=a=>`<ul class="objectives-list">${(a||[]).map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`;function rating(c){return `<section class="panel"><h2>Your course rating</h2><div class="rating-controls" role="group" aria-label="Rate this course from one to five stars">${[1,2,3,4,5].map(i=>`<button data-rating="${i}" class="${i<=(state.ratings[c.id]||0)?'selected':''}" aria-label="${i} stars" aria-pressed="${i===state.ratings[c.id]}" ${account?'':'disabled'}>★</button>`).join('')}<span id="rating-status">${state.ratings[c.id]?'Your rating: '+state.ratings[c.id]+'/5':'Not rated yet'}</span></div><p class="assessment-note">Saved privately to your account. These are your ratings, not fabricated community scores.</p></section>`;}
function overview(c){const first=c.lessons.find(l=>!complete(l))||c.lessons[0];return head(esc(c.level.toUpperCase())+' / AI ACADEMY',esc(c.title),esc(c.summary))+statusBanner()+`<div class="button-row" style="margin-bottom:30px">${button(url(c,first),'Continue course ↗')}${button('/academy','All AI courses',true)}${button('/community?course='+c.id,'Study together ↗',true)}<span class="tag">${c.credits} INTERNAL LEARNING CREDITS</span></div><div class="course-overview"><section class="panel"><h2>What you will be able to do</h2>${list(c.outcomes)}<h2>Before you begin</h2>${list(c.prerequisites)}${c.prerequisiteBridge?'<h2>Prerequisite bridge</h2>'+c.prerequisiteBridge.map(b=>'<h3>'+esc(b.title)+'</h3><p>'+esc(b.explanation)+'</p><p><strong>Practice:</strong> '+esc(b.practice)+'</p><p><strong>Check:</strong> '+esc(b.check)+'</p>').join(''):''}<h2>Setup and working environment</h2>${list(c.setup||['Read the prerequisites. Python examples identify their runtime requirements. Never paste an API key into this website.'])}</section><section class="panel"><h2>How completion works</h2><p>For every lesson: pass all checkpoint questions and submit the practical task with its rubric checked. Then submit the capstone project. This unlocks ${c.credits} course credits and a 100-point course bonus.</p><p>Checkpoints are automatically checked. Task submissions record your own evidence and self-assessment; they are not independently graded by a teacher or AI.</p><h2>Mastery gates</h2>${list(c.masteryCriteria||['Explain an unfamiliar variation without copying the example.','Test failure cases and justify the tradeoffs in your project.'])}</section></div><div class="section-head"><h2>The complete syllabus</h2><span class="muted">${c.lessons.length} lessons · ~${c.estimatedHours} hours including practice</span></div><section class="panel">${c.lessons.map((l,i)=>`<a class="lesson-row" href="${url(c,l)}"><span class="number">${complete(l)?'✓':String(i+1).padStart(2,'0')}</span><div><strong>${esc(l.title)}</strong><small>${l.minutes} min lesson estimate · checkpoint + practical task</small></div><span>↗</span></a>`).join('')}</section><div class="section-head"><h2>Your capstone project</h2></div><section class="panel"><h2>${esc(c.capstone.title)}</h2><div class="reader-prose">${esc(c.capstone.brief)}</div>${list(c.capstone.rubric)}${button('/tasks?task='+c.id+'-capstone','Open project submission ↗',true)}</section><div style="margin-top:25px">${rating(c)}</div>`;}
function taskForm(task){const saved=state.tasks[task.id];return `<h2>${esc(task.title)}</h2><div class="reader-prose">${esc(task.brief)}</div>${task.guidedSteps?'<h3>Guided steps</h3>'+list(task.guidedSteps):''}${task.independentExtension?'<h3>Independent extension</h3><p class="reader-prose">'+esc(task.independentExtension)+'</p>':''}<p class="assessment-note">Submit your code, observations, test results and explanation as text. This is a self-assessed submission: CodeTrail validates the evidence length and your rubric confirmations, not the correctness of the work.</p><form id="task-form"><label class="field">Your work and explanation<textarea class="task-evidence" id="task-evidence" minlength="120" maxlength="12000" required placeholder="Paste your work, describe how you tested it, and explain the result…">${esc(saved?.evidence||'')}</textarea><small>120–12,000 characters. Do not include credentials or private personal data.</small></label>${task.rubric.map((r,i)=>`<label class="rubric-check"><input type="checkbox" name="rubric" data-rubric="${i}" ${saved?'checked':''} required><span>${esc(r)}</span></label>`).join('')}<button class="button" id="submit-task" ${account?'':'disabled'}>${saved?'Update submission':'Submit task & earn '+(task.capstone?75:25)+' points'} ↗</button><p class="form-status" id="task-status" role="status">${saved?'Completed. Updating this submission does not award points twice.':account?'Points are awarded once for this task.':'Sign in to submit and earn points.'}</p></form>`;}
function lessonView(c,l){const idx=c.lessons.indexOf(l);const code=state.codeDrafts?.[l.id]??l.example.code;const allTabs=[['learn','Read & understand'],['lab','Worked example & lab'],['quiz','Checkpoint'],['task','Practical task']];return statusBanner()+`<div class="reader-layout"><aside class="lesson-outline"><p class="eyebrow">${esc(c.title)}</p>${c.lessons.map((x,i)=>`<a href="${url(c,x)}" class="${x.id===l.id?'current':''}" ${x.id===l.id?'aria-current="page"':''}><small>${complete(x)?'✓':String(i+1).padStart(2,'0')}</small>${esc(x.title)}</a>`).join('')}</aside><article><div class="reader-header"><p class="eyebrow">${esc(c.level.toUpperCase())} / LESSON ${idx+1} OF ${c.lessons.length}</p><h1>${esc(l.title)}</h1><p class="muted">${l.minutes} min lesson estimate, plus independent practice · ${complete(l)?'Lesson complete ✓':'Read, practice, check and submit'}</p></div><div class="reader-tabs" role="tablist">${allTabs.map(([t,label])=>`<button role="tab" data-reader-tab="${t}" aria-selected="false" aria-controls="pane-${t}">${label}</button>`).join('')}</div><section class="reader-pane" id="pane-learn" role="tabpanel"><section class="panel" style="margin-bottom:28px"><h2>Your learning objectives</h2>${list(l.objectives)}</section>${l.sections.map(s=>`<section class="reader-section"><h2>${esc(s.heading)}</h2><div class="reader-prose">${esc(s.body)}</div></section>`).join('')}<section class="panel"><h2>Common mistakes and debugging</h2>${list(l.pitfalls)}${l.debugging?l.debugging.map(d=>'<h3>'+esc(d.symptom)+'</h3><p class="reader-prose"><strong>Likely cause:</strong> '+esc(d.likelyCause)+'<br><strong>Try:</strong> '+esc(d.fix)+'</p>').join(''):''}${l.masteryGate?'<h3>Before moving on</h3>'+list(l.masteryGate.requirements)+'<p class="reader-prose">'+esc(l.masteryGate.ifNotYet)+'</p>':''}</section><h3>Go deeper with primary sources</h3>${l.resources.map(r=>`<a class="resource-link" href="${esc(r.url)}" target="_blank" rel="noopener noreferrer">${esc(r.title)} ↗</a>`).join('')}<p class="assessment-note">Original teaching content with links for further study. External documentation can change; check current package versions before using framework APIs.</p></section><section class="reader-pane" id="pane-lab" role="tabpanel" hidden><h2>${esc(l.example.title)}</h2><div class="reader-prose">${esc(l.example.explanation)}</div><pre>${esc(l.example.code)}</pre>${l.example.runInstructions?'<p class="notice">'+esc(l.example.runInstructions)+'</p>':''}${l.example.walkthrough?'<h3>Line-by-line walkthrough</h3>'+list(l.example.walkthrough):''}${l.example.expectedOutput?'<h3>Expected output</h3><pre>'+esc(l.example.expectedOutput)+'</pre>':''}<h3>Your practice editor</h3><p class="muted">${l.example.language==='python'?'The example is loaded below. Run it, change one thing, and explain what changed. Python runs on your device.':'This example is conceptual text. Use the editor for your own Python experiment; the conceptual text is not executable Python.'}</p><div class="example-lab"><div class="lab-top"><span>practice.py</span><span>PYTHON / ON-DEVICE</span></div><textarea id="editor" aria-label="Python practice code" spellcheck="false">${esc(l.example.language==='python'?code:(state.codeDrafts?.[l.id]??'# Write a small Python experiment here.\nprint("Ready to learn")'))}</textarea><div class="lab-controls"><button class="button" id="run-example">Run Python ▶</button><button class="button outline" id="stop-example">Stop</button><button class="button outline" id="save-code" ${account?'':'disabled'}>Save code</button><button class="button outline" id="ask-error">Explain output / error ✦</button></div><p class="code-save-status" id="code-save-status">${account?'Choose Save code to store this draft in your account.':'Sign in to save code. Guest changes stay in this tab.'}</p><div class="lab-output" id="output" role="status">Console output appears here. The tutor can read this output with your code when you ask for help.</div></div><p class="assessment-note">The optional tutor requires WebGPU and a model download. It can make mistakes; inspect and test corrections. External libraries and APIs may not be available in the browser runtime.</p></section><section class="reader-pane" id="pane-quiz" role="tabpanel" hidden><h2>Check your understanding</h2><p class="muted">Pass all ${l.quiz.length} questions to earn 15 points once. You can retry and learn from explanations.</p><form id="quiz-form">${l.quiz.map((q,i)=>`<fieldset class="checkpoint-item"><legend>${i+1}. ${esc(q.question)}</legend>${q.choices.map((ch,j)=>`<label class="quiz-choice"><input type="radio" name="question-${i}" value="${j}" required><span>${esc(ch)}</span></label>`).join('')}</fieldset>`).join('')}<button class="button" id="submit-quiz" ${account?'':'disabled'}>Check answers ↗</button><div id="quiz-feedback" role="status">${account?'':'Sign in to save checkpoint results.'}</div></form></section><section class="reader-pane panel" id="pane-task" role="tabpanel" hidden>${taskForm({...l.task,course:c,lesson:l})}</section><div class="academy-footer-nav">${button(url(c),'Course overview',true)}${button('/community?course='+c.id,'Course community ↗',true)}${idx<c.lessons.length-1?button(url(c,c.lessons[idx+1]),'Next lesson ↗'):button('/tasks?task='+c.id+'-capstone','Open capstone ↗')}</div></article></div>`;}
function tasksView(){const task=allTasks().find(t=>t.id===params.get('task'));if(task)return head(task.capstone?'CAPSTONE PROJECT':'PRACTICAL TASK',esc(task.title),esc(task.course.title))+statusBanner()+`<section class="panel">${taskForm(task)}</section><div class="button-row">${button(task.lesson?url(task.course,task.lesson):url(task.course),'Return to course',true)}${button('/tasks','All tasks',true)}</div>`;return head('PRACTICE THAT LEAVES EVIDENCE','TURN IDEAS INTO WORK.','Complete a practical task, show your thinking and collect learning points. Each task rewards completion once.')+statusBanner()+`<div class="filters"><label>COURSE<select id="task-course"><option value="all">All AI courses</option>${courses.map(c=>`<option value="${c.id}">${esc(c.title)}</option>`).join('')}</select></label><label>STATUS<select id="task-status-filter"><option value="all">All tasks</option><option value="todo">To do</option><option value="done">Completed</option></select></label></div><div id="task-list" class="task-list"></div>`;}
function achievementsView(){return head('YOUR LEARNING RECORD','EFFORT, MADE VISIBLE.','Earn points for checkpoints and task submissions. Complete every course requirement to unlock learning credits.')+statusBanner()+`<div class="reward-grid"><div class="reward"><strong>${summary.points}</strong><span>LEARNING POINTS</span></div><div class="reward"><strong>${summary.credits}</strong><span>COURSE CREDITS</span></div><div class="reward"><strong>${esc(summary.level)}</strong><span>LEARNING LEVEL</span></div></div><section class="panel"><h2>How points and credits work</h2><p>Passed lesson checkpoint: 15 points · Submitted lesson task: 25 points · Submitted capstone: 75 points · Completed course: 100 bonus points plus its course credits. Retrying or editing never duplicates rewards.</p><p>Learning levels: Launch (0), Explorer (250), Builder (1,000), Pioneer (2,500), Orbit (5,000). These are motivational labels, not verified skill ratings.</p><p class="assessment-note">Credits are internal CodeTrail achievements. They are not university credit, certification, cash, or hiring credentials. Task quality is self-assessed; quizzes check the supplied answers. The earlier Python/Java programming tracks are tracked separately and do not receive retroactive academy rewards.</p></section><div class="section-head"><h2>Course credit progress</h2></div><div class="academy-grid">${courses.map(courseCard).join('')}</div><div class="section-head"><h2>Earned activity</h2></div><section class="panel">${courses.flatMap(c=>c.lessons.filter(l=>state.quizPassed.includes(l.id)).map(l=>`<div class="lesson-row"><div><strong>${esc(l.title)}</strong><small>Checkpoint passed</small></div><span>+15 points</span></div>`)).join('')}${allTasks().filter(t=>state.tasks[t.id]).map(t=>`<a class="lesson-row" href="/tasks?task=${t.id}"><div><strong>${esc(t.title)}</strong><small>Self-assessed task submission</small></div><span>+${t.capstone?75:25} points</span></a>`).join('')}${summary.coursesCompleted.map(id=>{const c=courses.find(c=>c.id===id);return `<div class="lesson-row"><div><strong>${esc(c.title)}</strong><small>Course completed · ${c.credits} credits</small></div><span>+100 points</span></div>`;}).join('')}${!summary.points?'<p>No earned activity yet. Start with a lesson checkpoint and a practical task.</p>':''}</section>`;}
function memoryView(){const m=state.memory;return head('ACCOUNT MEMORY / YOU CHOOSE','KEEP THE CONTEXT.','Save recent tutor and feature-guide conversations to your account, and carry learning preferences between visits.')+statusBanner()+`<div class="notice">AI generation still happens on your device. Enabling account memory uploads chat questions and answers, which may include code, to your private account storage. Never include credentials or sensitive information. The latest 20 exchanges are retained across the tutor and feature guide; older exchanges roll off. Memory is off by default.</div><section class="panel memory-settings"><form id="memory-settings"><label><input type="checkbox" id="memory-enabled" ${m.enabled?'checked':''} ${account?'':'disabled'}><span>Save chat history to my account and reuse recent tutor conversations as context</span></label><label class="field" style="margin-top:24px">Learning preferences for the tutor<textarea id="memory-notes" maxlength="2000" placeholder="For example: explain from first principles; show expected output; use small Python examples." ${account?'':'disabled'}>${esc(m.notes)}</textarea><small>Up to 2,000 characters. Used as learning context when memory is enabled.</small></label><button class="button" ${account?'':'disabled'}>Save memory preferences ↗</button><p class="form-status" id="memory-status" role="status"></p></form></section><div class="section-head"><h2>Saved conversations (${m.turns.length}/20)</h2><button class="button outline" id="clear-memory" ${account&&m.turns.length?'':'disabled'}>Clear saved history</button></div><section class="panel">${m.turns.slice().reverse().map(t=>`<details class="memory-turn"><summary>${esc(t.context)} · ${new Date(t.at).toLocaleString()} · ${esc(t.user.slice(0,90))}</summary><p><strong>You</strong><br>${esc(t.user)}</p><p><strong>Assistant</strong></p><pre>${esc(t.assistant)}</pre></details>`).join('')||'<p>No saved conversations yet. Enable memory, then ask the coding tutor or homepage guide a question.</p>'}</section><p class="assessment-note">Disabling memory stops future saves and reuse; it retains saved history until you clear it. Clearing removes saved exchanges but does not erase open-tab text, profile preferences, course progress or code drafts.</p>`;}
function freeze(form,value){form.querySelectorAll('input,textarea,select,button').forEach(x=>x.disabled=value);}
function taskHandlers(task){const form=$('task-form');if(!form)return;form.oninput=()=>dirty.add('task');form.onsubmit=async e=>{e.preventDefault();const b=$('submit-task');freeze(form,true);$('task-status').textContent='Saving your task…';try{const before=summary.points;await request({action:'task',taskId:task.id,evidence:$('task-evidence').value,checks:[...form.querySelectorAll('[data-rubric]')].map(x=>x.checked)});dirty.delete('task');$('task-status').textContent='Task saved. '+(summary.points>before?'You earned '+(summary.points-before)+' points, including any newly unlocked course bonus.':'Your submission was updated without duplicate points.')+' Total: '+summary.points+' points · '+summary.credits+' credits.';b.textContent='Update submission ↗';}catch(err){$('task-status').textContent=err.message;}finally{freeze(form,false);}};}
function ratingHandlers(c){document.querySelectorAll('[data-rating]').forEach(b=>b.onclick=async()=>{document.querySelectorAll('[data-rating]').forEach(x=>x.disabled=true);try{await request({action:'rate',courseId:c.id,rating:Number(b.dataset.rating)});document.querySelectorAll('[data-rating]').forEach(x=>{x.classList.toggle('selected',Number(x.dataset.rating)<=state.ratings[c.id]);x.setAttribute('aria-pressed',String(Number(x.dataset.rating)===state.ratings[c.id]));});$('rating-status').textContent='Saved your rating: '+state.ratings[c.id]+'/5';}catch(e){$('rating-status').textContent=e.message;}finally{document.querySelectorAll('[data-rating]').forEach(x=>x.disabled=false);}});}
function lessonHandlers(c,l){function selectTab(tab){if(!['learn','lab','quiz','task'].includes(tab))tab='learn';document.querySelectorAll('[data-reader-tab]').forEach(b=>{b.classList.toggle('active',b.dataset.readerTab===tab);b.setAttribute('aria-selected',String(b.dataset.readerTab===tab));});document.querySelectorAll('.reader-pane').forEach(p=>p.hidden=p.id!=='pane-'+tab);history.replaceState(null,'',url(c,l,tab));}document.querySelectorAll('[data-reader-tab]').forEach(b=>b.onclick=()=>selectTab(b.dataset.readerTab));selectTab(params.get('tab')||'learn');window.academyTutorContext(l,$('editor').value);window.academyMarkDirty=()=>{dirty.add('code');$('code-save-status').textContent='Code changed. Choose Save code to keep this draft.';};$('editor').oninput=()=>{window.academyMarkDirty();saveDraft();};$('editor').onkeydown=e=>{if(e.key==='Tab'){e.preventDefault();e.target.setRangeText('    ',e.target.selectionStart,e.target.selectionEnd,'end');window.academyMarkDirty();saveDraft();}};$('save-code').onclick=async()=>{const b=$('save-code'),sentCode=$('editor').value;b.disabled=true;$('editor').readOnly=true;try{await request({action:'codeDraft',lessonId:l.id,code:sentCode});if($('editor').value===sentCode){dirty.delete('code');$('code-save-status').textContent='Code draft saved to your account';}else{$('code-save-status').textContent='Previous draft saved; newer edits still need saving.';}}catch(e){$('code-save-status').textContent=e.message;}finally{b.disabled=false;$('editor').readOnly=false;}};let runTimer=null;const stop=()=>{if(worker){worker.terminate();worker=null;}clearTimeout(runTimer);$('run-example').disabled=false;};$('stop-example').onclick=()=>{stop();$('output').textContent='Stopped.';};$('run-example').onclick=()=>{stop();$('run-example').disabled=true;$('output').textContent='Loading Python… The first run downloads the runtime.';worker=new Worker('/python-worker.js',{type:'module'});runTimer=setTimeout(()=>{stop();$('output').textContent='Stopped after 60 seconds. Check for an infinite loop or retry if the runtime download was slow.';},60000);worker.onmessage=e=>{if(e.data.ready){$('output').textContent='Running…';return;}$('output').textContent=(e.data.output||'')+(e.data.error?'\n'+e.data.error:'')||'No printed output. Use print() to inspect a value.';stop();};worker.onerror=()=>{stop();$('output').textContent='Python could not load. Check the connection and retry.';};worker.postMessage({code:$('editor').value,tests:null});};$('ask-error').onclick=()=>{selectTab('lab');window.codeTrailTutor.explainConsole();};$('quiz-form').onsubmit=async e=>{e.preventDefault();const b=$('submit-quiz');b.disabled=true;try{const answers=l.quiz.map((q,i)=>Number($('quiz-form').querySelector(`input[name="question-${i}"]:checked`)?.value??-1));const r=await request({action:'quiz',lessonId:l.id,answers});$('quiz-feedback').className='quiz-feedback';$('quiz-feedback').innerHTML=`<strong>${r.passed?'Checkpoint passed ✓ · 15 points awarded once':'Keep going. Review the explanations and try again.'}</strong>`+r.results.map((x,i)=>`<p>${i+1}. ${x.correct?'Correct':'Not yet'} — ${esc(x.explanation)}</p>`).join('');}catch(err){$('quiz-feedback').textContent=err.message;}finally{b.disabled=false;}};taskHandlers({...l.task,course:c,lesson:l});if(account)request({action:'visit',lessonId:l.id}).catch(()=>{});}
function memoryHandlers(){$('memory-settings').oninput=()=>dirty.add('memory');$('memory-settings').onsubmit=async e=>{e.preventDefault();const form=$('memory-settings'),b=form.querySelector('button');freeze(form,true);try{await request({action:'memorySettings',enabled:$('memory-enabled').checked,notes:$('memory-notes').value});dirty.delete('memory');$('memory-status').textContent=state.memory.enabled?'Account memory enabled. Future chat exchanges can be saved and reused.':'Account memory disabled. No new exchanges will be saved or reused.';}catch(err){$('memory-status').textContent=err.message;}finally{freeze(form,false);}};$('clear-memory').onclick=async()=>{if(dirty.has('memory')){$('memory-status').textContent='Save your memory preferences before clearing history.';return;}if(!confirm('Clear all saved chat exchanges? This cannot be undone. Course progress, profile and code drafts will stay.'))return;const b=$('clear-memory');b.disabled=true;try{await request({action:'memoryClear'});render();$('memory-status').textContent='Saved chat history cleared.';}catch(e){$('memory-status').textContent=e.message;b.disabled=false;}};}
function render(){const c=courses.find(c=>c.id===params.get('course')),l=c?.lessons.find(l=>l.id===params.get('lesson'));const titles={academy:'AI academy',tasks:'Practical tasks',achievements:'Credits & points',memory:'Chat memory'};document.title='CodeTrail — '+(l?.title||c?.title||titles[route]||'AI academy');$('breadcrumb').textContent=(titles[route]||'AI ACADEMY').toUpperCase();document.querySelectorAll('.sidebar nav a').forEach(a=>{if(a.getAttribute('href')==='/'+route){a.classList.add('active');a.setAttribute('aria-current','page');}});$('hub-account').textContent=account?'Sign out ↗':'Sign in ↗';$('hub-account').href=(account?'/signout-with-chatgpt':'/signin-with-chatgpt')+'?return_to='+encodeURIComponent(location.pathname+location.search);$('tutor-launch').hidden=!(route==='academy'&&l);$('hub-content').innerHTML=route==='tasks'?tasksView():route==='achievements'?achievementsView():route==='memory'?memoryView():l?lessonView(c,l):c?overview(c):academyHome();if(route==='academy'){if(c)window.LearnerFeatures?.trackView?.(c.id);if(l)lessonHandlers(c,l);else if(c)ratingHandlers(c);else{let level='all';const filter=()=>{const term=$('academy-search').value.trim().toLowerCase();window.LearnerFeatures?.trackSearch?.(term);const rows=courses.filter(c=>(level==='all'||c.level===level)&&(!term||[c.title,c.summary,...c.lessons.map(l=>l.title)].join(' ').toLowerCase().includes(term)));$('academy-courses').innerHTML=rows.map(courseCard).join('')||'<div class="empty">No matching courses. Try another topic or level.</div>';};$('academy-search').oninput=filter;document.querySelectorAll('[data-level]').forEach(b=>b.onclick=()=>{level=b.dataset.level;document.querySelectorAll('[data-level]').forEach(x=>x.classList.toggle('active',x===b));filter();});}}if(route==='tasks'){const task=allTasks().find(t=>t.id===params.get('task'));if(task)taskHandlers(task);else{const filter=()=>{$('task-list').innerHTML=allTasks().filter(t=>($('task-course').value==='all'||t.course.id===$('task-course').value)&&($('task-status-filter').value==='all'||($('task-status-filter').value==='done')===!!state.tasks[t.id])).map(t=>`<article class="task-card"><div><span class="tag">${state.tasks[t.id]?'COMPLETED ✓':t.capstone?'CAPSTONE · 75 POINTS':'TASK · 25 POINTS'}</span><h2>${esc(t.title)}</h2><p>${esc(t.course.title)}</p></div>${button('/tasks?task='+t.id,state.tasks[t.id]?'View submission ↗':'Open task ↗',true)}</article>`).join('')||'<div class="empty">No tasks match this filter.</div>';};$('task-course').onchange=filter;$('task-status-filter').onchange=filter;filter();}}if(route==='memory')memoryHandlers();}
async function start(){try{const r=await fetch('/academy-courses.json');if(!r.ok)throw Error('Courses unavailable');courses=await r.json();try{await request();}catch(e){if(e.status===401)guest=true;else error='Your cloud learning records could not load.';}render();}catch{$('hub-content').innerHTML='<div class="notice error">The AI courses could not load. Refresh to retry.</div>';}}addEventListener('beforeunload',e=>{if(dirty.size){e.preventDefault();e.returnValue='';}});start();
})();
